-- Helpers
-- ---------------------------------------------------------------------------

-- Lead of the owning team, or exec/admin.
create function public.can_manage_event(check_event_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_exec() or public.is_admin() or exists (
    select 1 from public.events e
    where e.id = check_event_id and public.leads_team(e.owner_team_id)
  );
$$;

create function public.is_on_event_team(check_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.event_registrations
    where event_team_id = check_team_id
      and user_id = (select auth.uid())
      and status <> 'cancelled'
  ) or exists (
    select 1 from public.event_teams where id = check_team_id and leader_id = (select auth.uid())
  );
$$;

-- Who may read a full (private) profile row.
create function public.can_view_profile(target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    target = (select auth.uid())
    or public.is_staff()
    -- leads: members of teams they lead
    or exists (
      select 1 from public.team_members tm
      join public.team_members me on me.team_id = tm.team_id
      where tm.member_id = target
        and me.member_id = (select auth.uid()) and me.team_role = 'lead' and me.status = 'active'
    )
    -- leads: registrants of events their teams own
    or exists (
      select 1 from public.event_registrations r
      join public.events e on e.id = r.event_id
      where r.user_id = target and public.leads_team(e.owner_team_id)
    )
    -- leads: students waiting for verification
    or (public.is_any_lead() and exists (
      select 1 from public.profiles p where p.id = target and p.student_status = 'pending'
    ))
    -- teammates in the same event team
    or exists (
      select 1 from public.event_registrations theirs
      where theirs.user_id = target
        and theirs.event_team_id is not null
        and theirs.status <> 'cancelled'
        and public.is_on_event_team(theirs.event_team_id)
    );
$$;

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

create policy "Read profiles within scope"
  on public.profiles for select to authenticated
  using (public.can_view_profile(id));

alter table public.events enable row level security;
alter table public.event_reviews enable row level security;
alter table public.event_teams enable row level security;
alter table public.event_registrations enable row level security;
alter table public.team_invites enable row level security;

create policy "Read published events or own scope"
  on public.events for select to anon, authenticated
  using (
    (status in ('published', 'completed') or (status = 'cancelled' and published_at is not null))
      and (visibility = 'public' or public.is_member())
    or created_by = (select auth.uid())
    or public.leads_team(owner_team_id)
    or public.is_staff()
  );

-- Members create drafts; status and review fields are not insertable.
create policy "Members create draft events"
  on public.events for insert to authenticated
  with check (created_by = (select auth.uid()) and public.is_member() and status = 'draft');

create policy "Edit events within scope"
  on public.events for update to authenticated
  using (
    (created_by = (select auth.uid()) and status in ('draft', 'changes_requested'))
    or (public.can_manage_event(id) and status not in ('archived', 'rejected'))
  )
  with check (
    (created_by = (select auth.uid()) and status in ('draft', 'changes_requested'))
    or (public.can_manage_event(id) and status not in ('archived', 'rejected'))
  );

create policy "Authors delete own drafts"
  on public.events for delete to authenticated
  using (created_by = (select auth.uid()) and status = 'draft');

revoke insert, update on public.events from anon, authenticated;
grant insert (
  title, summary, description, event_type, visibility, venue, starts_at, ends_at,
  reg_opens_at, reg_closes_at, capacity, participation, team_min, team_max,
  owner_team_id, domain_id, cover_path, created_by
) on public.events to authenticated;
grant update (
  title, summary, description, event_type, visibility, venue, starts_at, ends_at,
  reg_opens_at, reg_closes_at, capacity, participation, team_min, team_max,
  owner_team_id, domain_id, cover_path
) on public.events to authenticated;
revoke delete on public.events from anon;

create policy "Read reviews of visible proposals"
  on public.event_reviews for select to authenticated
  using (exists (
    select 1 from public.events e
    where e.id = event_id
      and (e.created_by = (select auth.uid()) or public.can_manage_event(e.id) or public.is_staff())
  ));
revoke insert, update, delete on public.event_reviews from anon, authenticated;

create policy "Read own, team, or managed registrations"
  on public.event_registrations for select to authenticated
  using (
    user_id = (select auth.uid())
    or (event_team_id is not null and public.is_on_event_team(event_team_id))
    or public.can_manage_event(event_id)
    or public.is_staff()
  );
revoke insert, update, delete on public.event_registrations from anon, authenticated;

create policy "Read own or managed event teams"
  on public.event_teams for select to authenticated
  using (public.is_on_event_team(id) or public.can_manage_event(event_id) or public.is_staff());
revoke insert, update, delete on public.event_teams from anon, authenticated;

create policy "Leaders and invitees read invites"
  on public.team_invites for select to authenticated
  using (
    public.is_on_event_team(event_team_id)
    or email = (select p.email from public.profiles p where p.id = (select auth.uid()))
    or exists (
      select 1 from public.event_teams t
      where t.id = event_team_id and public.can_manage_event(t.event_id)
    )
  );
revoke insert, update, delete on public.team_invites from anon, authenticated;
-- token_hash is never readable by clients.
revoke select on public.team_invites from anon, authenticated;
grant select (id, event_team_id, email, invited_by, status, expires_at, accepted_by, responded_at, created_at)
  on public.team_invites to authenticated;

-- Seat counts for public pages without exposing who registered.
create view public.event_seat_counts
with (security_barrier = true)
as
  select e.id as event_id,
         e.capacity,
         count(r.id) filter (where r.status in ('registered', 'attended')) as seats_taken
  from public.events e
  left join public.event_registrations r on r.event_id = e.id
  where e.status in ('published', 'completed', 'cancelled')
  group by e.id;

revoke all on public.event_seat_counts from anon, authenticated;
grant select on public.event_seat_counts to anon, authenticated;


-- ===== 20261028000500_projects.sql =====

-- Projects: showcase entries with contributors, domains, media and a review log.

create table public.projects (
  id uuid primary key default gen_random_uuid(),
  slug text unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (char_length(title) between 3 and 140),
  summary text check (char_length(summary) <= 300),
  problem text check (char_length(problem) <= 8000),
  solution text check (char_length(solution) <= 8000),
  outcomes text check (char_length(outcomes) <= 8000),
  hardware_details text check (char_length(hardware_details) <= 8000),
  software_details text check (char_length(software_details) <= 8000),
  repo_url text check (repo_url ~ '^https://' and char_length(repo_url) <= 500),
  demo_url text check (demo_url ~ '^https://' and char_length(demo_url) <= 500),
  status public.project_status not null default 'draft',
  visibility text not null default 'public' check (visibility in ('public', 'members')),
  owner_team_id uuid not null references public.teams (id),
  cover_path text check (char_length(cover_path) <= 500),
  created_by uuid not null references public.profiles (id),
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint projects_published_has_slug check (status <> 'published' or slug is not null)
);

create index projects_status_published_at_idx on public.projects (status, published_at desc);
create index projects_owner_team_id_idx on public.projects (owner_team_id);
create index projects_created_by_idx on public.projects (created_by);

create trigger projects_set_updated_at
  before update on public.projects
  for each row execute function public.set_updated_at();

create table public.project_contributors (
  project_id uuid not null references public.projects (id) on delete cascade,
  member_id uuid not null references public.profiles (id) on delete cascade,
  contribution text check (char_length(contribution) <= 200),
  confirmed_at timestamptz,
  is_public boolean not null default true,
  primary key (project_id, member_id)
);

create index project_contributors_member_id_idx on public.project_contributors (member_id);

create table public.project_domains (
  project_id uuid not null references public.projects (id) on delete cascade,
  domain_id uuid not null references public.domains (id) on delete cascade,
  primary key (project_id, domain_id)
);

create index project_domains_domain_id_idx on public.project_domains (domain_id);

create table public.project_media (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  storage_path text not null check (char_length(storage_path) <= 500),
  media_type text not null check (media_type in ('image', 'video', 'document')),
  caption text check (char_length(caption) <= 300),
  sort_order int not null default 0,
  uploaded_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

create index project_media_project_idx on public.project_media (project_id, sort_order);

create table public.project_reviews (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  reviewer_id uuid references public.profiles (id) on delete set null,
  decision text not null check (decision in ('approved', 'changes_requested', 'rejected')),
  notes text check (char_length(notes) <= 4000),
  created_at timestamptz not null default now()
);

create index project_reviews_project_idx on public.project_reviews (project_id, created_at);

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create function public.can_review_project(check_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_exec() or public.is_admin() or exists (
    select 1 from public.projects p
    where p.id = check_project_id and public.leads_team(p.owner_team_id)
  );
$$;

create function public.can_edit_project(check_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.projects p
    where p.id = check_project_id
      and p.created_by = (select auth.uid())
      and p.status in ('draft', 'changes_requested')
  );
$$;

create function public.can_view_project(check_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.projects p
    where p.id = check_project_id
      and (
        (p.status = 'published' and (p.visibility = 'public' or public.is_member()))
        or p.created_by = (select auth.uid())
        or exists (
          select 1 from public.project_contributors c
          where c.project_id = p.id and c.member_id = (select auth.uid())
        )
        or public.can_review_project(p.id)
        or public.is_staff()
      )
  );
$$;

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

alter table public.projects enable row level security;
alter table public.project_contributors enable row level security;
alter table public.project_domains enable row level security;
alter table public.project_media enable row level security;
alter table public.project_reviews enable row level security;

-- Author check is inline: a helper querying projects cannot see a row being inserted,
-- which would break INSERT ... RETURNING.
create policy "Read visible projects"
  on public.projects for select to anon, authenticated
  using (created_by = (select auth.uid()) or public.can_view_project(id));

create policy "Members create draft projects"
  on public.projects for insert to authenticated
  with check (created_by = (select auth.uid()) and public.is_member() and status = 'draft');

create policy "Edit projects within scope"
  on public.projects for update to authenticated
  using (public.can_edit_project(id) or (public.can_review_project(id) and status <> 'archived'))
  with check (
    (created_by = (select auth.uid()) and status in ('draft', 'changes_requested'))
    or public.can_review_project(id)
  );

create policy "Authors delete own drafts"
  on public.projects for delete to authenticated
  using (created_by = (select auth.uid()) and status = 'draft');

revoke insert, update on public.projects from anon, authenticated;
revoke delete on public.projects from anon;
grant insert (
  title, summary, problem, solution, outcomes, hardware_details, software_details,
  repo_url, demo_url, visibility, owner_team_id, cover_path, created_by
) on public.projects to authenticated;
grant update (
  title, summary, problem, solution, outcomes, hardware_details, software_details,
  repo_url, demo_url, visibility, owner_team_id, cover_path
) on public.projects to authenticated;

-- Public pages see only confirmed, public credits; collaborators see everything.
create policy "Read contributors"
  on public.project_contributors for select to anon, authenticated
  using (
    (confirmed_at is not null and is_public and exists (
      select 1 from public.projects p
      where p.id = project_id and p.status = 'published' and (p.visibility = 'public' or public.is_member())
    ))
    or member_id = (select auth.uid())
    or public.can_edit_project(project_id)
    or public.can_review_project(project_id)
    or public.is_staff()
  );
create policy "Authors add contributors to editable projects"
  on public.project_contributors for insert to authenticated
  with check (public.can_edit_project(project_id) and confirmed_at is null);
create policy "Authors remove contributors from editable projects"
  on public.project_contributors for delete to authenticated
  using (public.can_edit_project(project_id));
revoke update on public.project_contributors from anon, authenticated;
revoke insert on public.project_contributors from anon, authenticated;
grant insert (project_id, member_id, contribution) on public.project_contributors to authenticated;

create policy "Read project domains"
  on public.project_domains for select to anon, authenticated
  using (public.can_view_project(project_id));
create policy "Authors tag editable projects"
  on public.project_domains for insert to authenticated
  with check (public.can_edit_project(project_id));
create policy "Authors untag editable projects"
  on public.project_domains for delete to authenticated
  using (public.can_edit_project(project_id));
revoke update on public.project_domains from anon, authenticated;

create policy "Read project media"
  on public.project_media for select to anon, authenticated
  using (public.can_view_project(project_id));
create policy "Authors add media to editable projects"
  on public.project_media for insert to authenticated
  with check (public.can_edit_project(project_id) and uploaded_by = (select auth.uid()));
create policy "Authors edit media on editable projects"
  on public.project_media for update to authenticated
  using (public.can_edit_project(project_id))
  with check (public.can_edit_project(project_id));
create policy "Authors remove media from editable projects"
  on public.project_media for delete to authenticated
  using (public.can_edit_project(project_id));

create policy "Read reviews of visible projects"
  on public.project_reviews for select to authenticated
  using (exists (
    select 1 from public.projects p
    where p.id = project_id
      and (p.created_by = (select auth.uid()) or public.can_review_project(p.id) or public.is_staff())
  ));
revoke insert, update, delete on public.project_reviews from anon, authenticated;


-- ===== 20261028000600_recruitment_content.sql =====

-- Recruitment cycles, applications, private evaluations; announcements.

create table public.recruitment_cycles (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 3 and 100),
  description text check (char_length(description) <= 4000),
  opens_at timestamptz not null,
  closes_at timestamptz not null,
  status text not null default 'draft' check (status in ('draft', 'open', 'closed', 'archived')),
  questions jsonb not null default '[]'::jsonb check (jsonb_typeof(questions) = 'array'),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (closes_at > opens_at)
);

create trigger recruitment_cycles_set_updated_at
  before update on public.recruitment_cycles
  for each row execute function public.set_updated_at();

-- Reviewers assigned to a cycle (besides VP / President, who see everything).
create table public.recruitment_reviewers (
  cycle_id uuid not null references public.recruitment_cycles (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  assigned_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (cycle_id, user_id)
);

create table public.recruitment_applications (
  id uuid primary key default gen_random_uuid(),
  cycle_id uuid not null references public.recruitment_cycles (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  domain_prefs uuid[] not null default '{}' check (cardinality(domain_prefs) <= 5),
  team_prefs uuid[] not null default '{}' check (cardinality(team_prefs) <= 5),
  motivation text not null check (char_length(motivation) between 20 and 4000),
  experience text check (char_length(experience) <= 4000),
  portfolio_url text check (portfolio_url ~ '^https://' and char_length(portfolio_url) <= 500),
  answers jsonb not null default '{}'::jsonb check (jsonb_typeof(answers) = 'object'),
  status public.application_status not null default 'submitted',
  submitted_at timestamptz not null default now(),
  decided_at timestamptz,
  decided_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now(),
  unique (cycle_id, user_id)
);

create index recruitment_applications_cycle_status_idx on public.recruitment_applications (cycle_id, status);
create index recruitment_applications_user_idx on public.recruitment_applications (user_id);

create trigger recruitment_applications_set_updated_at
  before update on public.recruitment_applications
  for each row execute function public.set_updated_at();

create table public.recruitment_evaluations (
  id uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.recruitment_applications (id) on delete cascade,
  evaluator_id uuid references public.profiles (id) on delete set null,
  stage text not null check (stage in ('screening', 'interview')),
  score numeric(4, 1) check (score between 0 and 10),
  private_notes text check (char_length(private_notes) <= 4000),
  recommendation text check (recommendation in ('advance', 'hold', 'reject', 'select')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (application_id, evaluator_id, stage)
);

create trigger recruitment_evaluations_set_updated_at
  before update on public.recruitment_evaluations
  for each row execute function public.set_updated_at();

create table public.announcements (
  id uuid primary key default gen_random_uuid(),
  title text not null check (char_length(title) between 3 and 140),
  body text not null check (char_length(body) <= 20000),
  audience text not null check (audience in ('public', 'members', 'team')),
  team_id uuid references public.teams (id) on delete cascade,
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  published_at timestamptz,
  created_by uuid not null references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((audience = 'team') = (team_id is not null))
);

create index announcements_status_published_at_idx on public.announcements (status, published_at desc);

create trigger announcements_set_updated_at
  before update on public.announcements
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create function public.reviews_cycle(check_cycle_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_exec() or exists (
    select 1 from public.recruitment_reviewers
    where cycle_id = check_cycle_id and user_id = (select auth.uid())
  );
$$;

-- May this user write announcements for that audience?
create function public.can_announce(p_audience text, p_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_exec() or (p_audience = 'team' and public.leads_team(p_team_id));
$$;

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

alter table public.recruitment_cycles enable row level security;
alter table public.recruitment_reviewers enable row level security;
alter table public.recruitment_applications enable row level security;
alter table public.recruitment_evaluations enable row level security;
alter table public.announcements enable row level security;

create policy "Anyone reads announced cycles"
  on public.recruitment_cycles for select to anon, authenticated
  using (status in ('open', 'closed') or public.is_staff() or public.reviews_cycle(id));
create policy "Execs manage cycles"
  on public.recruitment_cycles for all to authenticated
  using (public.is_exec())
  with check (public.is_exec());

create policy "Reviewers see assignments"
  on public.recruitment_reviewers for select to authenticated
  using (user_id = (select auth.uid()) or public.is_exec());
create policy "Execs assign reviewers"
  on public.recruitment_reviewers for all to authenticated
  using (public.is_exec())
  with check (public.is_exec());

-- Applicants read their own application. Writes go through RPCs.
create policy "Applicants and reviewers read applications"
  on public.recruitment_applications for select to authenticated
  using (user_id = (select auth.uid()) or public.reviews_cycle(cycle_id));
revoke insert, update, delete on public.recruitment_applications from anon, authenticated;

-- Never visible to applicants.
create policy "Reviewers read evaluations"
  on public.recruitment_evaluations for select to authenticated
  using (exists (
    select 1 from public.recruitment_applications a
    where a.id = application_id
      and public.reviews_cycle(a.cycle_id)
      and a.user_id <> (select auth.uid())
  ));
revoke insert, update, delete on public.recruitment_evaluations from anon, authenticated;

create policy "Read announcements for my audience"
  on public.announcements for select to anon, authenticated
  using (
    (status = 'published' and (
      audience = 'public'
      or (audience = 'members' and public.is_member())
      or (audience = 'team' and public.in_team(team_id))
    ))
    or created_by = (select auth.uid())
    or public.is_staff()
  );
create policy "Authorised authors write drafts"
  on public.announcements for insert to authenticated
  with check (created_by = (select auth.uid()) and status = 'draft' and public.can_announce(audience, team_id));
create policy "Authors edit drafts"
  on public.announcements for update to authenticated
  using (created_by = (select auth.uid()) and status = 'draft')
  with check (created_by = (select auth.uid()) and status = 'draft' and public.can_announce(audience, team_id));
create policy "Authors delete drafts"
  on public.announcements for delete to authenticated
  using (created_by = (select auth.uid()) and status = 'draft');
revoke insert, update on public.announcements from anon, authenticated;
revoke delete on public.announcements from anon;
grant insert (title, body, audience, team_id, created_by) on public.announcements to authenticated;
grant update (title, body, audience, team_id) on public.announcements to authenticated;


-- ===== 20261028000700_identity_workflows.sql =====

-- Workflow RPCs: onboarding, student verification, roles, club team seats, member search.
-- Errors are raised with a stable UPPER_SNAKE code as the message; the app maps codes to copy.

create function public.complete_onboarding(
  p_full_name text,
  p_phone text,
  p_is_our_student boolean,
  p_college_name text default null,
  p_branch text default null,
  p_academic_year smallint default null,
  p_roll_number text default null
)
returns public.profiles
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where id = v_uid for update;
  if v_profile.id is null then
    raise exception 'PROFILE_NOT_FOUND';
  end if;
  if char_length(trim(coalesce(p_full_name, ''))) < 2 then
    raise exception 'NAME_REQUIRED';
  end if;
  if coalesce(p_phone, '') !~ '^\+?[0-9 ]{8,16}$' then
    raise exception 'PHONE_INVALID';
  end if;

  if v_profile.student_status = 'verified' then
    -- Verified identity fields are locked; only contact and study details change.
    update public.profiles
    set full_name = trim(p_full_name),
        phone = trim(p_phone),
        branch = coalesce(p_branch, branch),
        academic_year = coalesce(p_academic_year, academic_year),
        onboarded_at = coalesce(onboarded_at, now())
    where id = v_uid
    returning * into v_profile;
  elsif p_is_our_student then
    if p_branch is null or p_academic_year is null or char_length(trim(coalesce(p_roll_number, ''))) < 3 then
      raise exception 'STUDENT_DETAILS_REQUIRED';
    end if;
    update public.profiles
    set full_name = trim(p_full_name),
        phone = trim(p_phone),
        college_name = null,
        branch = trim(p_branch),
        academic_year = p_academic_year,
        roll_number = upper(trim(p_roll_number)),
        student_status = 'pending',
        onboarded_at = coalesce(onboarded_at, now())
    where id = v_uid
    returning * into v_profile;
  else
    if v_profile.member_status in ('member', 'applicant') then
      raise exception 'MEMBERS_MUST_BE_STUDENTS';
    end if;
    if char_length(trim(coalesce(p_college_name, ''))) < 2 then
      raise exception 'COLLEGE_REQUIRED';
    end if;
    update public.profiles
    set full_name = trim(p_full_name),
        phone = trim(p_phone),
        college_name = trim(p_college_name),
        branch = nullif(trim(coalesce(p_branch, '')), ''),
        academic_year = p_academic_year,
        roll_number = null,
        student_status = 'external',
        onboarded_at = coalesce(onboarded_at, now())
    where id = v_uid
    returning * into v_profile;
  end if;

  return v_profile;
end;
$$;

create function public.verify_student(p_user_id uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_status public.student_status;
begin
  if not (public.is_any_lead() or public.is_exec()) then
    raise exception 'NOT_ALLOWED';
  end if;
  if p_user_id = v_uid then
    raise exception 'CANNOT_VERIFY_SELF';
  end if;

  select student_status into v_status from public.profiles where id = p_user_id for update;
  if v_status is distinct from 'pending' then
    raise exception 'INVALID_STATUS';
  end if;

  begin
    update public.profiles
    set student_status = case when p_approve then 'verified'::public.student_status else 'rejected'::public.student_status end
    where id = p_user_id;
  exception when unique_violation then
    raise exception 'ROLL_NUMBER_TAKEN';
  end;

  perform private.notify(
    p_user_id,
    'student_verification',
    case when p_approve then 'Your student status is verified' else 'We could not verify your student status' end,
    case when p_approve then null else 'Check your roll number in your profile and contact the club if it is correct.' end,
    '/portal/profile'
  );
  perform private.audit(
    case when p_approve then 'student.verified' else 'student.rejected' end,
    'profile', p_user_id
  );
end;
$$;

create function public.assign_role(p_user_id uuid, p_role public.app_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED';
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then
    raise exception 'USER_NOT_FOUND';
  end if;

  insert into public.user_roles (user_id, role, assigned_by)
  values (p_user_id, p_role, v_uid)
  on conflict (user_id, role) do nothing;

  if found then
    perform private.audit('role.assigned', 'profile', p_user_id, jsonb_build_object('role', p_role));
    perform private.notify(p_user_id, 'role', 'You have a new role: ' || replace(p_role::text, '_', ' '), null, '/manage');
  end if;
end;
$$;

create function public.revoke_role(p_user_id uuid, p_role public.app_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_user();
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED';
  end if;
  if p_role = 'admin' and (select count(*) from public.user_roles where role = 'admin') <= 1 then
    raise exception 'LAST_ADMIN';
  end if;

  delete from public.user_roles where user_id = p_user_id and role = p_role;
  if found then
    perform private.audit('role.revoked', 'profile', p_user_id, jsonb_build_object('role', p_role));
  end if;
end;
$$;

-- Add, change or remove (p_team_role null) a member's seat on a club team.
create function public.set_team_member(p_team_id uuid, p_user_id uuid, p_team_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_team_name text;
begin
  perform private.require_user();
  if not (public.is_exec() or public.is_admin()) then
    raise exception 'NOT_ALLOWED';
  end if;
  select name into v_team_name from public.teams where id = p_team_id;
  if v_team_name is null then
    raise exception 'TEAM_NOT_FOUND';
  end if;

  if p_team_role is null then
    update public.team_members set status = 'inactive'
    where team_id = p_team_id and member_id = p_user_id;
    perform private.audit('team_member.removed', 'team', p_team_id, jsonb_build_object('user_id', p_user_id));
    return;
  end if;

  if p_team_role not in ('member', 'deputy', 'lead') then
    raise exception 'INVALID_TEAM_ROLE';
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id and member_status = 'member') then
    raise exception 'NOT_A_MEMBER';
  end if;

  insert into public.team_members (team_id, member_id, team_role, status)
  values (p_team_id, p_user_id, p_team_role, 'active')
  on conflict (team_id, member_id) do update set team_role = excluded.team_role, status = 'active';

  perform private.audit('team_member.set', 'team', p_team_id,
    jsonb_build_object('user_id', p_user_id, 'team_role', p_team_role));
  perform private.notify(p_user_id, 'team', 'You are now ' || p_team_role || ' of ' || v_team_name, null, '/portal/teams');
end;
$$;

-- Member picker for project contributors and team management.
create function public.search_members(p_query text)
returns table (id uuid, full_name text, avatar_url text, branch text, academic_year smallint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_user();
  if not (public.is_member() or public.is_staff()) then
    raise exception 'NOT_ALLOWED';
  end if;
  if char_length(trim(coalesce(p_query, ''))) < 2 then
    return;
  end if;

  return query
    select p.id, p.full_name, p.avatar_url, p.branch, p.academic_year
    from public.profiles p
    where p.member_status = 'member'
      and p.full_name ilike '%' || replace(replace(trim(p_query), '%', ''), '_', '') || '%'
    order by p.full_name
    limit 10;
end;
$$;


-- ===== 20261028000800_event_workflows.sql =====

-- Workflow RPCs: event proposals, two-stage review, publication, registration and event teams.

-- ---------------------------------------------------------------------------
-- Internal guards
-- ---------------------------------------------------------------------------

create function private.require_onboarded(p_uid uuid)
returns public.profiles
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where id = p_uid;
  if v_profile.onboarded_at is null then
    raise exception 'ONBOARDING_REQUIRED';
  end if;
  return v_profile;
end;
$$;

-- Locks the event row so seat counts are checked one registration at a time.
create function private.lock_open_event(p_event_id uuid)
returns public.events
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.events;
begin
  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null or v_event.status <> 'published'
     or (v_event.visibility = 'members' and not public.is_member()) then
    raise exception 'EVENT_NOT_FOUND';
  end if;
  if v_event.reg_opens_at is not null and now() < v_event.reg_opens_at then
    raise exception 'REGISTRATION_NOT_OPEN';
  end if;
  if now() >= coalesce(v_event.reg_closes_at, v_event.starts_at, 'infinity'::timestamptz) then
    raise exception 'REGISTRATION_CLOSED';
  end if;
  return v_event;
end;
$$;

create function private.assert_can_take_seat(p_event public.events, p_uid uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if exists (
    select 1 from public.event_registrations
    where event_id = p_event.id and user_id = p_uid and status <> 'cancelled'
  ) then
    raise exception 'ALREADY_REGISTERED';
  end if;
  if p_event.capacity is not null and (
    select count(*) from public.event_registrations
    where event_id = p_event.id and status in ('registered', 'attended')
  ) >= p_event.capacity then
    raise exception 'EVENT_FULL';
  end if;
end;
$$;

create function private.normalize_emails(p_emails text[])
returns text[]
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_result text[];
begin
  select coalesce(array_agg(distinct e), '{}')
  into v_result
  from (select lower(trim(x)) as e from unnest(coalesce(p_emails, '{}')) as x) s
  where e <> '';

  if exists (select 1 from unnest(v_result) e where e !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then
    raise exception 'INVITE_EMAIL_INVALID';
  end if;
  return v_result;
end;
$$;

create function private.create_team_invite(p_team_id uuid, p_email text, p_inviter uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_token text := private.new_token();
  v_invite_id uuid;
  v_team public.event_teams;
  v_event public.events;
  v_leader_name text;
begin
  select * into v_team from public.event_teams where id = p_team_id;
  select * into v_event from public.events where id = v_team.event_id;
  select full_name into v_leader_name from public.profiles where id = v_team.leader_id;

  begin
    insert into public.team_invites (event_team_id, email, invited_by, token_hash, expires_at)
    values (
      p_team_id, p_email, p_inviter, private.hash_token(v_token),
      coalesce(v_event.reg_closes_at, v_event.starts_at, now() + interval '14 days')
    )
    returning id into v_invite_id;
  exception when unique_violation then
    raise exception 'ALREADY_INVITED';
  end;

  perform private.enqueue_email(
    p_email,
    'team-invite',
    jsonb_build_object(
      'token', v_token,
      'event_title', v_event.title,
      'event_slug', v_event.slug,
      'event_starts_at', v_event.starts_at,
      'team_name', v_team.name,
      'leader_name', v_leader_name
    ),
    'team-invite:' || v_invite_id || ':' || private.hash_token(v_token)
  );

  -- Invitee may already have an account.
  insert into public.notifications (user_id, kind, title, body, target_url)
  select p.id, 'team_invite', v_leader_name || ' invited you to team ' || v_team.name,
         v_event.title, '/invite/' || v_token
  from public.profiles p
  where p.email = p_email;
end;
$$;

create function private.refresh_team_status(p_team_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_team public.event_teams;
  v_min smallint;
  v_count int;
  v_new_status text;
begin
  select * into v_team from public.event_teams where id = p_team_id for update;
  if v_team.status = 'withdrawn' then
    return v_team.status;
  end if;

  select team_min into v_min from public.events where id = v_team.event_id;
  select count(*) into v_count
  from public.event_registrations
  where event_team_id = p_team_id and status <> 'cancelled';

  v_new_status := case when v_count >= v_min then 'complete' else 'forming' end;
  if v_new_status <> v_team.status then
    update public.event_teams set status = v_new_status where id = p_team_id;
    if v_new_status = 'complete' then
      perform private.notify(v_team.leader_id, 'team_complete', 'Team ' || v_team.name || ' is complete',
        'Your team has enough members to take part.', '/portal/registrations');
    end if;
  end if;
  return v_new_status;
end;
$$;

-- ---------------------------------------------------------------------------
-- Proposals and review
-- ---------------------------------------------------------------------------

create function public.submit_event(p_event_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_event public.events;
begin
  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null or v_event.created_by <> v_uid then
    raise exception 'EVENT_NOT_FOUND';
  end if;
  if v_event.status not in ('draft', 'changes_requested') then
    raise exception 'INVALID_STATUS';
  end if;
  if not public.is_member() then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_event.summary is null or v_event.description is null or v_event.venue is null
     or v_event.starts_at is null then
    raise exception 'EVENT_INCOMPLETE';
  end if;
  if v_event.starts_at <= now() then
    raise exception 'EVENT_IN_PAST';
  end if;

  update public.events
  set status = 'pending_review',
      is_major = is_major
        or event_type in ('hackathon', 'competition', 'external')
        or coalesce(capacity, 0) > 100
  where id = p_event_id;

  insert into public.notifications (user_id, kind, title, body, target_url)
  select tm.member_id, 'event_review', 'New event proposal: ' || v_event.title, null, '/manage/events/' || p_event_id
  from public.team_members tm
  where tm.team_id = v_event.owner_team_id and tm.team_role = 'lead' and tm.status = 'active'
    and tm.member_id <> v_uid;

  perform private.enqueue_telegram('event-submitted',
    jsonb_build_object('event_id', p_event_id, 'title', v_event.title),
    'event-submitted:' || p_event_id || ':' || extract(epoch from now())::bigint);
  perform private.audit('event.submitted', 'event', p_event_id);
end;
$$;

create function public.review_event(
  p_event_id uuid,
  p_decision text,
  p_notes text default null,
  p_mark_major boolean default false
)
returns public.event_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_event public.events;
  v_stage text;
  v_new_status public.event_status;
  v_creator_email text;
begin
  if p_decision not in ('approved', 'changes_requested', 'rejected') then
    raise exception 'INVALID_DECISION';
  end if;
  if p_decision <> 'approved' and char_length(trim(coalesce(p_notes, ''))) < 5 then
    raise exception 'NOTES_REQUIRED';
  end if;

  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null then
    raise exception 'EVENT_NOT_FOUND';
  end if;
  if v_event.created_by = v_uid then
    raise exception 'CANNOT_REVIEW_OWN';
  end if;

  if v_event.status = 'pending_review' then
    v_stage := 'lead';
    if not (public.leads_team(v_event.owner_team_id) or public.is_exec()) then
      raise exception 'NOT_ALLOWED';
    end if;
  elsif v_event.status = 'lead_approved' and v_event.is_major then
    v_stage := 'final';
    if not public.is_exec() then
      raise exception 'NOT_ALLOWED';
    end if;
  else
    raise exception 'INVALID_STATUS';
  end if;

  v_new_status := case p_decision
    when 'changes_requested' then 'changes_requested'::public.event_status
    when 'rejected' then 'rejected'::public.event_status
    else case v_stage when 'lead' then 'lead_approved'::public.event_status else 'final_approved'::public.event_status end
  end;

  update public.events
  set status = v_new_status,
      is_major = is_major or (v_stage = 'lead' and coalesce(p_mark_major, false))
  where id = p_event_id
  returning * into v_event;

  insert into public.event_reviews (event_id, stage, reviewer_id, decision, notes)
  values (p_event_id, v_stage, v_uid, p_decision, nullif(trim(coalesce(p_notes, '')), ''));

  perform private.notify(v_event.created_by, 'event_decision',
    case p_decision
      when 'approved' then 'Your proposal "' || v_event.title || '" was approved'
      when 'changes_requested' then 'Changes requested on "' || v_event.title || '"'
      else 'Your proposal "' || v_event.title || '" was not approved'
    end,
    p_notes, '/portal/proposals/' || p_event_id);

  select email into v_creator_email from public.profiles where id = v_event.created_by;
  perform private.enqueue_email(v_creator_email, 'event-decision',
    jsonb_build_object('event_id', p_event_id, 'title', v_event.title, 'stage', v_stage,
                       'decision', p_decision, 'notes', p_notes),
    'event-decision:' || p_event_id || ':' || v_stage || ':' || extract(epoch from now())::bigint);

  -- Major events now wait on VP / President.
  if v_new_status = 'lead_approved' and v_event.is_major then
    insert into public.notifications (user_id, kind, title, target_url)
    select distinct ur.user_id, 'event_review', 'Final approval needed: ' || v_event.title, '/manage/events/' || p_event_id
    from public.user_roles ur
    where ur.role in ('vice_president', 'president') and ur.user_id <> v_event.created_by;
  end if;

  perform private.audit('event.reviewed', 'event', p_event_id,
    jsonb_build_object('stage', v_stage, 'decision', p_decision));
  return v_new_status;
end;
$$;

create function public.publish_event(p_event_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.events;
  v_slug text;
begin
  perform private.require_user();
  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null then
    raise exception 'EVENT_NOT_FOUND';
  end if;
  if not public.can_manage_event(p_event_id) then
    raise exception 'NOT_ALLOWED';
  end if;
  if not ((v_event.status = 'lead_approved' and not v_event.is_major) or v_event.status = 'final_approved') then
    raise exception 'NOT_READY';
  end if;
  if v_event.starts_at is null or v_event.starts_at <= now() then
    raise exception 'EVENT_IN_PAST';
  end if;

  v_slug := coalesce(
    v_event.slug,
    coalesce(nullif(left(public.slugify(v_event.title), 60), ''), 'event')
      || '-' || left(replace(v_event.id::text, '-', ''), 6)
  );

  update public.events
  set status = 'published',
      slug = trim(both '-' from v_slug),
      published_at = now(),
      reg_closes_at = coalesce(reg_closes_at, starts_at)
  where id = p_event_id;

  perform private.notify(v_event.created_by, 'event_published', '"' || v_event.title || '" is live', null, '/events/' || v_slug);
  perform private.audit('event.published', 'event', p_event_id);
  return v_slug;
end;
$$;

create function public.cancel_event(p_event_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.events;
begin
  perform private.require_user();
  if char_length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'REASON_REQUIRED';
  end if;
  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null or not public.can_manage_event(p_event_id) then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_event.status <> 'published' then
    raise exception 'INVALID_STATUS';
  end if;

  update public.events set status = 'cancelled' where id = p_event_id;

  insert into public.notifications (user_id, kind, title, body, target_url)
  select r.user_id, 'event_cancelled', v_event.title || ' is cancelled', p_reason, '/events/' || v_event.slug
  from public.event_registrations r
  where r.event_id = p_event_id and r.status = 'registered';

  insert into public.email_outbox (channel, to_address, template, payload, idempotency_key)
  select 'email', p.email, 'event-cancelled',
         jsonb_build_object('title', v_event.title, 'reason', p_reason, 'starts_at', v_event.starts_at),
         'event-cancelled:' || r.id
  from public.event_registrations r
  join public.profiles p on p.id = r.user_id
  where r.event_id = p_event_id and r.status = 'registered'
  on conflict (idempotency_key) do nothing;

  perform private.audit('event.cancelled', 'event', p_event_id, jsonb_build_object('reason', p_reason));
end;
$$;

-- ---------------------------------------------------------------------------
-- Registration
-- ---------------------------------------------------------------------------

create function public.register_individual(p_event_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles := private.require_onboarded(v_uid);
  v_event public.events := private.lock_open_event(p_event_id);
  v_registration_id uuid;
begin
  if v_event.participation <> 'individual' then
    raise exception 'TEAM_EVENT';
  end if;
  perform private.assert_can_take_seat(v_event, v_uid);

  insert into public.event_registrations (event_id, user_id)
  values (p_event_id, v_uid)
  returning id into v_registration_id;

  perform private.notify(v_uid, 'registration', 'You are registered for ' || v_event.title, null, '/portal/registrations');
  perform private.enqueue_email(v_profile.email, 'registration-confirmed',
    jsonb_build_object('title', v_event.title, 'slug', v_event.slug, 'starts_at', v_event.starts_at,
                       'venue', v_event.venue, 'registration_id', v_registration_id),
    'registration:' || v_registration_id);
  return v_registration_id;
end;
$$;

create function public.create_event_team(p_event_id uuid, p_team_name text, p_invite_emails text[])
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles := private.require_onboarded(v_uid);
  v_event public.events := private.lock_open_event(p_event_id);
  v_emails text[] := private.normalize_emails(p_invite_emails);
  v_team_id uuid;
  v_email text;
begin
  if v_event.participation <> 'team' then
    raise exception 'INDIVIDUAL_EVENT';
  end if;
  if char_length(trim(coalesce(p_team_name, ''))) < 2 then
    raise exception 'TEAM_NAME_REQUIRED';
  end if;
  if v_profile.email = any (v_emails) then
    raise exception 'CANNOT_INVITE_SELF';
  end if;
  if cardinality(v_emails) > v_event.team_max - 1 then
    raise exception 'TOO_MANY_INVITES';
  end if;
  perform private.assert_can_take_seat(v_event, v_uid);

  begin
    insert into public.event_teams (event_id, name, leader_id)
    values (p_event_id, trim(p_team_name), v_uid)
    returning id into v_team_id;
  exception when unique_violation then
    raise exception 'TEAM_NAME_TAKEN';
  end;

  insert into public.event_registrations (event_id, user_id, event_team_id, team_role)
  values (p_event_id, v_uid, v_team_id, 'leader');

  foreach v_email in array v_emails loop
    perform private.create_team_invite(v_team_id, v_email, v_uid);
  end loop;

  perform private.refresh_team_status(v_team_id);
  perform private.enqueue_email(v_profile.email, 'team-created',
    jsonb_build_object('title', v_event.title, 'slug', v_event.slug, 'team_name', trim(p_team_name),
                       'team_min', v_event.team_min, 'invited', to_jsonb(v_emails)),
    'team-created:' || v_team_id);
  return v_team_id;
end;
$$;

-- Read-only preview for /invite/[token]; works before sign-in.
create function public.get_invite(p_token text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'status', case when i.status = 'pending' and i.expires_at <= now() then 'expired' else i.status end,
    'email_hint', left(i.email, 1) || '***@' || split_part(i.email, '@', 2),
    'expires_at', i.expires_at,
    'team_name', t.name,
    'team_status', t.status,
    'leader_name', lp.full_name,
    'event_title', e.title,
    'event_slug', e.slug,
    'event_starts_at', e.starts_at,
    'event_venue', e.venue
  )
  from public.team_invites i
  join public.event_teams t on t.id = i.event_team_id
  join public.events e on e.id = t.event_id
  join public.profiles lp on lp.id = t.leader_id
  where i.token_hash = private.hash_token(p_token);
$$;

create function private.lock_invite_for_user(p_token text, p_email text)
returns public.team_invites
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invite public.team_invites;
begin
  select * into v_invite from public.team_invites where token_hash = private.hash_token(p_token) for update;
  if v_invite.id is null then
    raise exception 'INVITE_NOT_FOUND';
  end if;
  if v_invite.status <> 'pending' then
    raise exception 'INVITE_%', upper(v_invite.status);
  end if;
  if v_invite.expires_at <= now() then
    raise exception 'INVITE_EXPIRED';
  end if;
  if v_invite.email <> p_email then
    raise exception 'INVITE_EMAIL_MISMATCH';
  end if;
  return v_invite;
end;
$$;

create function public.accept_invite(p_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles := private.require_onboarded(v_uid);
  v_invite public.team_invites := private.lock_invite_for_user(p_token, v_profile.email);
  v_team public.event_teams;
  v_event public.events;
  v_registration_id uuid;
begin
  select * into v_team from public.event_teams where id = v_invite.event_team_id for update;
  if v_team.status = 'withdrawn' then
    raise exception 'TEAM_WITHDRAWN';
  end if;
  v_event := private.lock_open_event(v_team.event_id);
  perform private.assert_can_take_seat(v_event, v_uid);
  if (select count(*) from public.event_registrations
      where event_team_id = v_team.id and status <> 'cancelled') >= v_event.team_max then
    raise exception 'TEAM_FULL';
  end if;

  insert into public.event_registrations (event_id, user_id, event_team_id, team_role)
  values (v_event.id, v_uid, v_team.id, 'member')
  returning id into v_registration_id;

  update public.team_invites
  set status = 'accepted', accepted_by = v_uid, responded_at = now()
  where id = v_invite.id;

  perform private.refresh_team_status(v_team.id);
  perform private.notify(v_team.leader_id, 'team_invite_accepted',
    v_profile.full_name || ' joined ' || v_team.name, v_event.title, '/portal/registrations');
  perform private.enqueue_email(v_profile.email, 'registration-confirmed',
    jsonb_build_object('title', v_event.title, 'slug', v_event.slug, 'starts_at', v_event.starts_at,
                       'venue', v_event.venue, 'team_name', v_team.name, 'registration_id', v_registration_id),
    'registration:' || v_registration_id);
  return v_registration_id;
end;
$$;

create function public.decline_invite(p_token text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles;
  v_invite public.team_invites;
  v_team public.event_teams;
begin
  select * into v_profile from public.profiles where id = v_uid;
  v_invite := private.lock_invite_for_user(p_token, v_profile.email);
  select * into v_team from public.event_teams where id = v_invite.event_team_id;

  update public.team_invites set status = 'declined', responded_at = now() where id = v_invite.id;
  perform private.notify(v_team.leader_id, 'team_invite_declined',
    coalesce(nullif(v_profile.full_name, ''), v_profile.email) || ' declined your invite to ' || v_team.name,
    null, '/portal/registrations');
end;
$$;

create function private.require_team_leader(p_team_id uuid, p_uid uuid)
returns public.event_teams
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_team public.event_teams;
begin
  select * into v_team from public.event_teams where id = p_team_id for update;
  if v_team.id is null or v_team.leader_id <> p_uid then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_team.status = 'withdrawn' then
    raise exception 'TEAM_WITHDRAWN';
  end if;
  return v_team;
end;
$$;

create function public.add_team_invites(p_team_id uuid, p_emails text[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_team public.event_teams := private.require_team_leader(p_team_id, v_uid);
  v_event public.events := private.lock_open_event(v_team.event_id);
  v_emails text[] := private.normalize_emails(p_emails);
  v_email text;
  v_used int;
begin
  if (select email from public.profiles where id = v_uid) = any (v_emails) then
    raise exception 'CANNOT_INVITE_SELF';
  end if;
  select
    (select count(*) from public.event_registrations where event_team_id = p_team_id and status <> 'cancelled')
    + (select count(*) from public.team_invites where event_team_id = p_team_id and status = 'pending' and expires_at > now())
  into v_used;
  if v_used + cardinality(v_emails) > v_event.team_max then
    raise exception 'TOO_MANY_INVITES';
  end if;

  foreach v_email in array v_emails loop
    perform private.create_team_invite(p_team_id, v_email, v_uid);
  end loop;
end;
$$;

create function public.revoke_team_invite(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_invite public.team_invites;
begin
  select * into v_invite from public.team_invites where id = p_invite_id for update;
  if v_invite.id is null then
    raise exception 'INVITE_NOT_FOUND';
  end if;
  perform private.require_team_leader(v_invite.event_team_id, v_uid);
  if v_invite.status <> 'pending' then
    raise exception 'INVALID_STATUS';
  end if;
  update public.team_invites set status = 'revoked', responded_at = now() where id = p_invite_id;
end;
$$;

-- New token, new email. The old link stops working.
create function public.resend_team_invite(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_invite public.team_invites;
begin
  select * into v_invite from public.team_invites where id = p_invite_id for update;
  if v_invite.id is null then
    raise exception 'INVITE_NOT_FOUND';
  end if;
  perform private.require_team_leader(v_invite.event_team_id, v_uid);
  if v_invite.status not in ('pending', 'expired', 'declined') then
    raise exception 'INVALID_STATUS';
  end if;

  update public.team_invites set status = 'revoked', responded_at = now() where id = p_invite_id;
  perform private.create_team_invite(v_invite.event_team_id, v_invite.email, v_uid);
end;
$$;

create function public.withdraw_registration(p_registration_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_reg public.event_registrations;
  v_event public.events;
  v_team public.event_teams;
begin
  select * into v_reg from public.event_registrations where id = p_registration_id for update;
  if v_reg.id is null or v_reg.user_id <> v_uid then
    raise exception 'REGISTRATION_NOT_FOUND';
  end if;
  if v_reg.status <> 'registered' then
    raise exception 'INVALID_STATUS';
  end if;
  select * into v_event from public.events where id = v_reg.event_id;
  if v_event.starts_at <= now() then
    raise exception 'EVENT_STARTED';
  end if;

  if v_reg.team_role = 'leader' then
    -- Leader leaving withdraws the whole team.
    select * into v_team from public.event_teams where id = v_reg.event_team_id for update;
    update public.event_teams set status = 'withdrawn' where id = v_team.id;
    update public.team_invites set status = 'revoked', responded_at = now()
    where event_team_id = v_team.id and status = 'pending';

    insert into public.notifications (user_id, kind, title, body, target_url)
    select r.user_id, 'team_withdrawn', 'Team ' || v_team.name || ' withdrew', v_event.title, '/portal/registrations'
    from public.event_registrations r
    where r.event_team_id = v_team.id and r.status = 'registered' and r.user_id <> v_uid;

    update public.event_registrations set status = 'cancelled'
    where event_team_id = v_team.id and status = 'registered';
  else
    update public.event_registrations set status = 'cancelled' where id = p_registration_id;
    if v_reg.event_team_id is not null then
      select * into v_team from public.event_teams where id = v_reg.event_team_id;
      perform private.refresh_team_status(v_team.id);
      perform private.notify(v_team.leader_id, 'team_member_left',
        'A member left ' || v_team.name, v_event.title, '/portal/registrations');
    end if;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Scheduled maintenance (Vercel cron calls this with the service role, e.g. hourly)
-- ---------------------------------------------------------------------------

create function public.run_scheduled_maintenance()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reminded int;
  v_withdrawn int;
  v_expired int;
  v_completed int;
begin
  -- 1. Remind leaders of incomplete teams 24 hours before registration closes.
  insert into public.email_outbox (channel, to_address, template, payload, idempotency_key)
  select 'email', p.email, 'team-incomplete-reminder',
         jsonb_build_object('title', e.title, 'slug', e.slug, 'team_name', t.name,
                            'team_min', e.team_min, 'closes_at', coalesce(e.reg_closes_at, e.starts_at)),
         'team-reminder:' || t.id
  from public.event_teams t
  join public.events e on e.id = t.event_id
  join public.profiles p on p.id = t.leader_id
  where t.status = 'forming'
    and e.status = 'published'
    and coalesce(e.reg_closes_at, e.starts_at) between now() and now() + interval '24 hours'
  on conflict (idempotency_key) do nothing;
  get diagnostics v_reminded = row_count;

  -- 2. Withdraw teams still incomplete after registration closed.
  with closed as (
    update public.event_teams t
    set status = 'withdrawn'
    from public.events e
    where e.id = t.event_id
      and t.status = 'forming'
      and coalesce(e.reg_closes_at, e.starts_at) <= now()
    returning t.id, t.name, t.leader_id, e.title
  ), cancelled as (
    update public.event_registrations r
    set status = 'cancelled'
    from closed
    where r.event_team_id = closed.id and r.status = 'registered'
    returning r.user_id, closed.name, closed.title
  )
  insert into public.notifications (user_id, kind, title, body, target_url)
  select user_id, 'team_withdrawn', 'Team ' || name || ' did not reach the minimum size',
         'Registration for ' || title || ' has closed, so the team was withdrawn.', '/portal/registrations'
  from cancelled;
  get diagnostics v_withdrawn = row_count;

  -- 3. Expire stale invites.
  update public.team_invites set status = 'expired'
  where status = 'pending' and expires_at <= now();
  get diagnostics v_expired = row_count;

  -- 4. Mark finished events completed.
  update public.events set status = 'completed'
  where status = 'published' and coalesce(ends_at, starts_at + interval '1 day') <= now();
  get diagnostics v_completed = row_count;

  return jsonb_build_object('reminded', v_reminded, 'withdrawn_members', v_withdrawn,
                            'expired_invites', v_expired, 'completed_events', v_completed);
end;
$$;


-- ===== 20261028000900_project_recruitment_workflows.sql =====

-- Workflow RPCs: projects, recruitment, announcements.

-- ---------------------------------------------------------------------------
-- Projects
-- ---------------------------------------------------------------------------

create function public.submit_project(p_project_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_project public.projects;
begin
  select * into v_project from public.projects where id = p_project_id for update;
  if v_project.id is null or v_project.created_by <> v_uid then
    raise exception 'PROJECT_NOT_FOUND';
  end if;
  if v_project.status not in ('draft', 'changes_requested') then
    raise exception 'INVALID_STATUS';
  end if;
  if not public.is_member() then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_project.summary is null or v_project.problem is null or v_project.solution is null then
    raise exception 'PROJECT_INCOMPLETE';
  end if;

  -- The author is always a confirmed contributor.
  insert into public.project_contributors (project_id, member_id, confirmed_at)
  values (p_project_id, v_uid, now())
  on conflict (project_id, member_id) do update set confirmed_at = coalesce(public.project_contributors.confirmed_at, now());

  update public.projects set status = 'submitted' where id = p_project_id;

  insert into public.notifications (user_id, kind, title, target_url)
  select c.member_id, 'contribution_confirm', 'Confirm your credit on "' || v_project.title || '"', '/portal/projects'
  from public.project_contributors c
  where c.project_id = p_project_id and c.confirmed_at is null;

  insert into public.notifications (user_id, kind, title, target_url)
  select tm.member_id, 'project_review', 'New project to review: ' || v_project.title, '/manage/projects/' || p_project_id
  from public.team_members tm
  where tm.team_id = v_project.owner_team_id and tm.team_role = 'lead' and tm.status = 'active'
    and tm.member_id <> v_uid;

  perform private.audit('project.submitted', 'project', p_project_id);
end;
$$;

create function public.start_project_review(p_project_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_project public.projects;
begin
  select * into v_project from public.projects where id = p_project_id for update;
  if v_project.id is null or not public.can_review_project(p_project_id) or v_project.created_by = v_uid then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_project.status <> 'submitted' then
    raise exception 'INVALID_STATUS';
  end if;
  update public.projects set status = 'in_review' where id = p_project_id;
end;
$$;

create function public.review_project(p_project_id uuid, p_decision text, p_notes text default null)
returns public.project_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_project public.projects;
  v_new_status public.project_status;
  v_slug text;
begin
  if p_decision not in ('approved', 'changes_requested', 'rejected') then
    raise exception 'INVALID_DECISION';
  end if;
  if p_decision <> 'approved' and char_length(trim(coalesce(p_notes, ''))) < 5 then
    raise exception 'NOTES_REQUIRED';
  end if;

  select * into v_project from public.projects where id = p_project_id for update;
  if v_project.id is null or not public.can_review_project(p_project_id) then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_project.created_by = v_uid then
    raise exception 'CANNOT_REVIEW_OWN';
  end if;
  if v_project.status not in ('submitted', 'in_review') then
    raise exception 'INVALID_STATUS';
  end if;

  v_new_status := case p_decision
    when 'approved' then 'published'::public.project_status
    when 'changes_requested' then 'changes_requested'::public.project_status
    else 'rejected'::public.project_status
  end;

  if v_new_status = 'published' then
    v_slug := coalesce(
      v_project.slug,
      trim(both '-' from coalesce(nullif(left(public.slugify(v_project.title), 60), ''), 'project'))
        || '-' || left(replace(v_project.id::text, '-', ''), 6)
    );
  end if;

  update public.projects
  set status = v_new_status,
      slug = coalesce(v_slug, slug),
      published_at = case when v_new_status = 'published' then now() else published_at end
  where id = p_project_id;

  insert into public.project_reviews (project_id, reviewer_id, decision, notes)
  values (p_project_id, v_uid, p_decision, nullif(trim(coalesce(p_notes, '')), ''));

  perform private.notify(v_project.created_by, 'project_decision',
    case p_decision
      when 'approved' then '"' || v_project.title || '" is published'
      when 'changes_requested' then 'Changes requested on "' || v_project.title || '"'
      else '"' || v_project.title || '" was not approved'
    end,
    p_notes,
    case when v_new_status = 'published' then '/projects/' || v_slug else '/portal/projects' end);
  perform private.audit('project.reviewed', 'project', p_project_id, jsonb_build_object('decision', p_decision));
  return v_new_status;
end;
$$;

create function public.confirm_contribution(p_project_id uuid, p_accept boolean, p_is_public boolean default true)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_project public.projects;
begin
  select * into v_project from public.projects where id = p_project_id;
  if not exists (
    select 1 from public.project_contributors where project_id = p_project_id and member_id = v_uid
  ) then
    raise exception 'NOT_A_CONTRIBUTOR';
  end if;

  if p_accept then
    update public.project_contributors
    set confirmed_at = coalesce(confirmed_at, now()), is_public = coalesce(p_is_public, true)
    where project_id = p_project_id and member_id = v_uid;
  else
    delete from public.project_contributors where project_id = p_project_id and member_id = v_uid;
    perform private.notify(v_project.created_by, 'contribution_declined',
      'A contributor declined credit on "' || v_project.title || '"', null, '/portal/projects');
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Recruitment
-- ---------------------------------------------------------------------------

create function public.submit_application(
  p_cycle_id uuid,
  p_domain_prefs uuid[],
  p_team_prefs uuid[],
  p_motivation text,
  p_experience text default null,
  p_portfolio_url text default null,
  p_answers jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_profile public.profiles := private.require_onboarded(v_uid);
  v_cycle public.recruitment_cycles;
  v_domains uuid[] := array(select distinct unnest(coalesce(p_domain_prefs, '{}')));
  v_teams uuid[] := array(select distinct unnest(coalesce(p_team_prefs, '{}')));
  v_application_id uuid;
begin
  if v_profile.member_status = 'member' then
    raise exception 'ALREADY_MEMBER';
  end if;
  if v_profile.member_status = 'suspended' or v_profile.student_status not in ('pending', 'verified') then
    raise exception 'NOT_ELIGIBLE';
  end if;

  select * into v_cycle from public.recruitment_cycles where id = p_cycle_id for share;
  if v_cycle.id is null or v_cycle.status <> 'open' or now() not between v_cycle.opens_at and v_cycle.closes_at then
    raise exception 'CYCLE_CLOSED';
  end if;
  if cardinality(v_domains) = 0 then
    raise exception 'DOMAIN_REQUIRED';
  end if;
  if (select count(*) from public.domains where id = any (v_domains) and is_active) <> cardinality(v_domains)
     or (select count(*) from public.teams where id = any (v_teams) and is_active) <> cardinality(v_teams) then
    raise exception 'INVALID_PREFERENCE';
  end if;

  begin
    insert into public.recruitment_applications (
      cycle_id, user_id, domain_prefs, team_prefs, motivation, experience, portfolio_url, answers
    )
    values (
      p_cycle_id, v_uid, v_domains, v_teams, trim(p_motivation),
      nullif(trim(coalesce(p_experience, '')), ''), nullif(trim(coalesce(p_portfolio_url, '')), ''),
      coalesce(p_answers, '{}'::jsonb)
    )
    returning id into v_application_id;
  exception when unique_violation then
    raise exception 'ALREADY_APPLIED';
  end;

  update public.profiles set member_status = 'applicant' where id = v_uid and member_status = 'none';

  perform private.enqueue_email(v_profile.email, 'application-received',
    jsonb_build_object('cycle_name', v_cycle.name, 'full_name', v_profile.full_name),
    'application-received:' || v_application_id);
  perform private.enqueue_telegram('application-submitted',
    jsonb_build_object('cycle_name', v_cycle.name, 'full_name', v_profile.full_name),
    'application-submitted:' || v_application_id);
  return v_application_id;
end;
$$;

-- Applicant who no longer has an open application goes back to member_status 'none'.
create function private.reset_applicant_status(p_user_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.profiles
  set member_status = 'none'
  where id = p_user_id
    and member_status = 'applicant'
    and not exists (
      select 1 from public.recruitment_applications
      where user_id = p_user_id and status in ('submitted', 'screening', 'shortlisted', 'interview', 'waitlisted')
    );
$$;

create function public.withdraw_application(p_application_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_app public.recruitment_applications;
begin
  select * into v_app from public.recruitment_applications where id = p_application_id for update;
  if v_app.id is null or v_app.user_id <> v_uid then
    raise exception 'APPLICATION_NOT_FOUND';
  end if;
  if v_app.status in ('selected', 'rejected', 'withdrawn') then
    raise exception 'INVALID_STATUS';
  end if;
  update public.recruitment_applications set status = 'withdrawn' where id = p_application_id;
  perform private.reset_applicant_status(v_uid);
end;
$$;

-- Reviewer pipeline moves. Final outcomes after interview belong to decide_application.
create function public.move_application(p_application_id uuid, p_status public.application_status)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_app public.recruitment_applications;
  v_email text;
  v_cycle_name text;
begin
  select * into v_app from public.recruitment_applications where id = p_application_id for update;
  if v_app.id is null or not public.reviews_cycle(v_app.cycle_id) or v_app.user_id = v_uid then
    raise exception 'NOT_ALLOWED';
  end if;
  if not (
    (v_app.status = 'submitted' and p_status = 'screening')
    or (v_app.status = 'screening' and p_status in ('shortlisted', 'rejected'))
    or (v_app.status = 'shortlisted' and p_status in ('interview', 'rejected'))
  ) then
    raise exception 'INVALID_TRANSITION';
  end if;

  update public.recruitment_applications
  set status = p_status,
      decided_at = case when p_status = 'rejected' then now() else decided_at end,
      decided_by = case when p_status = 'rejected' then v_uid else decided_by end
  where id = p_application_id;

  select email into v_email from public.profiles where id = v_app.user_id;
  select name into v_cycle_name from public.recruitment_cycles where id = v_app.cycle_id;

  if p_status = 'rejected' then
    perform private.reset_applicant_status(v_app.user_id);
    perform private.enqueue_email(v_email, 'application-outcome',
      jsonb_build_object('cycle_name', v_cycle_name, 'outcome', 'rejected'),
      'application-outcome:' || p_application_id);
  elsif p_status = 'interview' then
    perform private.enqueue_email(v_email, 'application-interview',
      jsonb_build_object('cycle_name', v_cycle_name),
      'application-interview:' || p_application_id);
  end if;
  perform private.notify(v_app.user_id, 'application', 'Your application was updated', null, '/portal/applications');
  perform private.audit('application.moved', 'recruitment_application', p_application_id,
    jsonb_build_object('from', v_app.status, 'to', p_status));
end;
$$;

create function public.evaluate_application(
  p_application_id uuid,
  p_stage text,
  p_score numeric,
  p_private_notes text,
  p_recommendation text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_app public.recruitment_applications;
begin
  select * into v_app from public.recruitment_applications where id = p_application_id;
  if v_app.id is null or not public.reviews_cycle(v_app.cycle_id) or v_app.user_id = v_uid then
    raise exception 'NOT_ALLOWED';
  end if;

  insert into public.recruitment_evaluations (application_id, evaluator_id, stage, score, private_notes, recommendation)
  values (p_application_id, v_uid, p_stage, p_score, p_private_notes, p_recommendation)
  on conflict (application_id, evaluator_id, stage) do update
  set score = excluded.score,
      private_notes = excluded.private_notes,
      recommendation = excluded.recommendation;
end;
$$;

create function public.decide_application(
  p_application_id uuid,
  p_decision public.application_status,
  p_domain_ids uuid[] default null,
  p_team_ids uuid[] default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_app public.recruitment_applications;
  v_profile public.profiles;
  v_cycle_name text;
begin
  if not public.is_exec() then
    raise exception 'NOT_ALLOWED';
  end if;
  if p_decision not in ('selected', 'waitlisted', 'rejected') then
    raise exception 'INVALID_DECISION';
  end if;

  select * into v_app from public.recruitment_applications where id = p_application_id for update;
  if v_app.id is null then
    raise exception 'APPLICATION_NOT_FOUND';
  end if;
  if v_app.user_id = v_uid then
    raise exception 'CANNOT_REVIEW_OWN';
  end if;
  if v_app.status not in ('shortlisted', 'interview', 'waitlisted') then
    raise exception 'INVALID_STATUS';
  end if;

  select * into v_profile from public.profiles where id = v_app.user_id for update;
  select name into v_cycle_name from public.recruitment_cycles where id = v_app.cycle_id;

  if p_decision = 'selected' then
    if v_profile.student_status <> 'verified' then
      raise exception 'STUDENT_NOT_VERIFIED';
    end if;

    update public.profiles set member_status = 'member' where id = v_profile.id;

    insert into public.member_domains (member_id, domain_id)
    select v_profile.id, d from unnest(coalesce(p_domain_ids, v_app.domain_prefs)) d
    on conflict do nothing;

    insert into public.team_members (team_id, member_id, team_role, status)
    select t, v_profile.id, 'member', 'active' from unnest(coalesce(p_team_ids, v_app.team_prefs)) t
    on conflict (team_id, member_id) do update set status = 'active';
  end if;

  update public.recruitment_applications
  set status = p_decision, decided_at = now(), decided_by = v_uid
  where id = p_application_id;

  if p_decision = 'rejected' then
    perform private.reset_applicant_status(v_profile.id);
  end if;

  perform private.notify(v_profile.id, 'application',
    case p_decision
      when 'selected' then 'Welcome to SIC!'
      when 'waitlisted' then 'You are on the waitlist'
      else 'Your application outcome is ready'
    end,
    null, case when p_decision = 'selected' then '/portal' else '/portal/applications' end);
  perform private.enqueue_email(v_profile.email, 'application-outcome',
    jsonb_build_object('cycle_name', v_cycle_name, 'outcome', p_decision, 'full_name', v_profile.full_name),
    'application-outcome:' || p_application_id || ':' || p_decision);
  perform private.audit('application.decided', 'recruitment_application', p_application_id,
    jsonb_build_object('decision', p_decision));
end;
$$;

-- ---------------------------------------------------------------------------
-- Announcements
-- ---------------------------------------------------------------------------

create function public.publish_announcement(p_announcement_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_row public.announcements;
begin
  select * into v_row from public.announcements where id = p_announcement_id for update;
  if v_row.id is null or not (v_row.created_by = v_uid or public.is_exec()) then
    raise exception 'NOT_ALLOWED';
  end if;
  if not public.can_announce(v_row.audience, v_row.team_id) then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_row.status <> 'draft' then
    raise exception 'INVALID_STATUS';
  end if;

  update public.announcements set status = 'published', published_at = now() where id = p_announcement_id;

  insert into public.notifications (user_id, kind, title, target_url)
  select p.id, 'announcement', v_row.title, '/portal/notices'
  from public.profiles p
  where p.id <> v_uid
    and (
      (v_row.audience = 'members' and p.member_status = 'member')
      or (v_row.audience = 'team' and exists (
        select 1 from public.team_members tm
        where tm.team_id = v_row.team_id and tm.member_id = p.id and tm.status = 'active'
      ))
    );

  perform private.audit('announcement.published', 'announcement', p_announcement_id,
    jsonb_build_object('audience', v_row.audience));
end;
$$;

create function public.archive_announcement(p_announcement_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_row public.announcements;
begin
  select * into v_row from public.announcements where id = p_announcement_id for update;
  if v_row.id is null or not (v_row.created_by = v_uid or public.is_exec()) then
    raise exception 'NOT_ALLOWED';
  end if;
  if v_row.status <> 'published' then
    raise exception 'INVALID_STATUS';
  end if;
  update public.announcements set status = 'archived' where id = p_announcement_id;
end;
$$;


-- ===== 20261028001000_grants_storage.sql =====

-- Function privileges and storage buckets.

-- Supabase grants EXECUTE on new public functions to anon and authenticated by default.
-- Start from nothing, then grant deliberately.
revoke execute on all functions in schema public from public, anon, authenticated;
revoke execute on all functions in schema private from public, anon, authenticated;

-- RLS helpers: policies on tables readable by anon call these, so anon needs them too.
grant execute on function
  public.has_role(public.app_role),
  public.is_exec(),
  public.is_admin(),
  public.is_staff(),
  public.is_member(),
  public.leads_team(uuid),
  public.is_any_lead(),
  public.in_team(uuid),
  public.can_manage_event(uuid),
  public.is_on_event_team(uuid),
  public.can_view_profile(uuid),
  public.can_review_project(uuid),
  public.can_edit_project(uuid),
  public.can_view_project(uuid),
  public.reviews_cycle(uuid),
  public.can_announce(text, uuid),
  public.slugify(text)
to anon, authenticated;

-- Invite preview works before sign-in.
grant execute on function public.get_invite(text) to anon, authenticated;

-- Workflow RPCs: signed-in users only. Each function checks its own permissions.
grant execute on function
  public.complete_onboarding(text, text, boolean, text, text, smallint, text),
  public.verify_student(uuid, boolean),
  public.assign_role(uuid, public.app_role),
  public.revoke_role(uuid, public.app_role),
  public.set_team_member(uuid, uuid, text),
  public.search_members(text),
  public.submit_event(uuid),
  public.review_event(uuid, text, text, boolean),
  public.publish_event(uuid),
  public.cancel_event(uuid, text),
  public.register_individual(uuid),
  public.create_event_team(uuid, text, text[]),
  public.accept_invite(text),
  public.decline_invite(text),
  public.add_team_invites(uuid, text[]),
  public.revoke_team_invite(uuid),
  public.resend_team_invite(uuid),
  public.withdraw_registration(uuid),
  public.submit_project(uuid),
  public.start_project_review(uuid),
  public.review_project(uuid, text, text),
  public.confirm_contribution(uuid, boolean, boolean),
  public.submit_application(uuid, uuid[], uuid[], text, text, text, jsonb),
  public.withdraw_application(uuid),
  public.move_application(uuid, public.application_status),
  public.evaluate_application(uuid, text, numeric, text, text),
  public.decide_application(uuid, public.application_status, uuid[], uuid[]),
  public.publish_announcement(uuid),
  public.archive_announcement(uuid)
to authenticated;

-- Cron only.
grant execute on function public.run_scheduled_maintenance() to service_role;

-- Future functions start locked as well.
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Storage
--   avatars       public read; users write inside "<uid>/"
--   public-media  public read; members write inside "<uid>/" (event covers, project media)
--   private-docs  no public read; owner and staff read via signed URLs
-- Store random file names; never trust the uploaded filename.
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('avatars', 'avatars', true, 2097152, array['image/jpeg', 'image/png', 'image/webp']),
  ('public-media', 'public-media', true, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'video/mp4', 'application/pdf']),
  ('private-docs', 'private-docs', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png'])
on conflict (id) do nothing;

create policy "Users upload own avatar"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Users replace own avatar"
  on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Users delete own avatar"
  on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "Members upload media"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'public-media'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and public.is_member()
  );
create policy "Members delete own media"
  on storage.objects for delete to authenticated
  using (bucket_id = 'public-media' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "Owners and staff read private docs"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'private-docs'
    and ((storage.foldername(name))[1] = (select auth.uid())::text or public.is_staff())
  );
create policy "Users upload own private docs"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'private-docs' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Users delete own private docs"
  on storage.objects for delete to authenticated
  using (bucket_id = 'private-docs' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- ===== 20261028001100_public_views.sql =====

-- Read-only views for public pages that need names without exposing profiles.
-- Each view filters to rows the person agreed to show.

-- Credited contributors on published projects (contributor confirmed and chose public credit).
create view public.public_project_contributors
with (security_barrier = true)
as
  select c.project_id, c.member_id, c.contribution, p.full_name, p.avatar_url
  from public.project_contributors c
  join public.profiles p on p.id = c.member_id
  join public.projects pr on pr.id = c.project_id
  where c.confirmed_at is not null
    and c.is_public
    and pr.status = 'published'
    and pr.visibility = 'public';

-- Office bearers who opted into a public profile.
create view public.public_leadership
with (security_barrier = true)
as
  select ur.role, p.id as member_id, p.full_name, p.avatar_url, p.bio, p.branch
  from public.user_roles ur
  join public.profiles p on p.id = ur.user_id
  where ur.role in ('president', 'vice_president', 'faculty_coordinator')
    and p.public_profile;

-- Names of fellow members, for members and staff only. No contact details.
create view public.member_directory
with (security_barrier = true)
as
  select id, full_name, avatar_url, branch, academic_year
  from public.profiles
  where member_status = 'member'
    and (public.is_member() or public.is_staff());

revoke all on public.public_project_contributors, public.public_leadership, public.member_directory from anon, authenticated;
grant select on public.public_project_contributors, public.public_leadership to anon, authenticated;
grant select on public.member_directory to authenticated;


-- ===== 20261028001200_reviewer_profile_access.sql =====

-- Recruitment reviewers need to read the profile (name, branch, roll number) of
-- applicants in cycles they are assigned to. Same rules as before, plus that clause.

create or replace function public.can_view_profile(target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    target = (select auth.uid())
    or public.is_staff()
    or exists (
      select 1 from public.team_members tm
      join public.team_members me on me.team_id = tm.team_id
      where tm.member_id = target
        and me.member_id = (select auth.uid()) and me.team_role = 'lead' and me.status = 'active'
    )
    or exists (
      select 1 from public.event_registrations r
      join public.events e on e.id = r.event_id
      where r.user_id = target and public.leads_team(e.owner_team_id)
    )
    or (public.is_any_lead() and exists (
      select 1 from public.profiles p where p.id = target and p.student_status = 'pending'
    ))
    or exists (
      select 1 from public.event_registrations theirs
      where theirs.user_id = target
        and theirs.event_team_id is not null
        and theirs.status <> 'cancelled'
        and public.is_on_event_team(theirs.event_team_id)
    )
    or exists (
      select 1 from public.recruitment_applications a
      where a.user_id = target and public.reviews_cycle(a.cycle_id)
    );
$$;

revoke execute on function public.can_view_profile(uuid) from public;
grant execute on function public.can_view_profile(uuid) to anon, authenticated;


